insert into public.noam_ramzi_hints (exercise_id,hint_1,hint_2,hint_3,status,source,source_id,source_exercise_text,review_note) values
('G7-T01-A-Q01א','במדידת גבהים ועומקים, איזה מצב משמש כנקודת הייחוס, והאם ירידה מתחת לפני הים מבטאת תנועה לכיוון החיובי או השלילי?','מקמו בדמיונכם את המצב הנתון ביחס לנקודת האפס, וקבעו לאיזה צד של הציר הוא שייך.','בדקו איזה סימן מתמטי מייצג את הצד שבו בחרתם על הציר, וכתבו באמצעותו את המספר המכוון המתאים.','review','zero-spoiler-v2.1','G7-T01-A-Q01א','צוללן ירד לעומק של 15 מטרים מתחת לפני הים. כתבו מספר מכוון המבטא את מיקומו ביחס לגובה פני הים.','לא מוצג לתלמידים. הרמזים לא מתאימים לסעיף שמופה, ולא נמצא סעיף מתאים באותו נושא. יש לבדוק ולתקן לפני סימון verified.'),
('G7-T01-A-Q01ב','כאשר משווים בין מספרים על ציר המספרים, כיצד המיקום שלהם ביחס לנקודת האפס והמרחק ממנה קובעים מי מהם גדול יותר?','מקמו בדמיונכם כל אחד מהמספרים ביחס לנקודת האפס, והשוו את המרחקים שלהם ממנה.','קבעו מי מהמספרים נמצא ימינה יותר על גבי הציר (או האם הם מתלכדים באותה נקודה), ובחרו את סימן ההשוואה המתאים.','review','zero-spoiler-v2.1','G7-T01-A-Q01ב','השוו בין המספרים והציבו סימן מתאים: $-3.5 ___ -3$','לא מוצג לתלמידים. הרמזים מתאימים רק בחלקם לסעיף שמופה, ונבדקה העברה ל־G7-T01-B-Q11ב ונפסלה. יש לבדוק ולתקן לפני סימון verified.'),
('G7-T01-A-Q04א','לאילו כיוונים שונים על גבי הציר ניתן להתקדם מנקודת האפס באותו מרחק נתון?','מדדו את המרחק הנתון פעם אחת לכיוון ימין של האפס ופעם נוספת לכיוון שמאל של האפס.','רשמו את המספרים המכוונים המתאימים לנקודות שמצאתם בכל צד של הציר.','verified','zero-spoiler-v2.1','G7-T01-C-Q01א','נתון כי המרחק של מספר מסוים מנקודת האפס הוא 6 יחידות. אילו מספרים יכולים להתאים לתיאור זה?','הרמזים נכתבו לתרגיל אחר מזה שמופה (G7-T01-E-Q01א), והועברו לסעיף זה באותו נושא. נבדק מול הסעיף המודפס: הרמזים מתאימים לו, נכונים ואינם מגלים את התשובה. שני בודקים לא מצאו סיבה לפסול.'),
('G7-T01-A-Q34א','כיצד מעבר לצורת רישום אחידה של מספר עם נקודה מסייע בהשוואת מיקומים על גבי הציר?','המירו תחילה את השבר לצורה עם נקודה, ומקמו בדמיונכם את שני הערכים ביחס לנקודת האפס.','קבעו מי מהמספרים נמצא ימינה יותר על גבי הציר (או האם הם מתלכדים באותה נקודה), ובחרו את סימן ההשוואה המתאים.','verified','zero-spoiler-v2.1','G7-T01-B-Q01א','השוו בין המספרים והציבו סימן מתאים: $-1/2 ___ -0.8$','הרמזים נכתבו לתרגיל אחר מזה שמופה (G7-T01-B-Q01א), והועברו לסעיף זה באותו נושא. נבדק מול הסעיף המודפס: הרמזים מתאימים לו, נכונים ואינם מגלים את התשובה. שני בודקים לא מצאו סיבה לפסול.'),
('G7-T02-B-Q03ב','כאשר מוסיפים מספר שלילי על גבי ציר המספרים, לאיזה כיוון נעים מנקודת ההתחלה?','התחילו בנקודה הראשונה על גבי הציר, ובצעו צעדים בכיוון המתאים למספר הנוסף.','בדקו לאיזו נקודה מספרית הגעתם על גבי הציר בסיום התנועה, ורשמו אותה.','verified','zero-spoiler-v2.1','G7-T02-A-Q01א','חשבו: $(-4) + (-3)$','הרמזים נכתבו לתרגיל אחר מזה שמופה (G7-T02-A-Q01א), והועברו לסעיף זה באותו נושא. נבדק מול הסעיף המודפס: הרמזים מתאימים לו, נכונים ואינם מגלים את התשובה. שני בודקים לא מצאו סיבה לפסול.'),
('G7-T02-B-Q15א','כיצד ניתן להמיר פעולת חיסור לפעולת חיבור עם המספר הנגדי?','כתבו את תרגיל החיסור כתרגיל חיבור של המספר הנגדי, ומקמו את התנועה על גבי הציר.','קבעו את המרחק והכיוון הסופי ביחס לנקודת האפס כדי לרשום את התוצאה.','verified','zero-spoiler-v2.1','G7-T02-A-Q01ב','חשבו: $(+5) - (+8)$','הרמזים נכתבו לתרגיל אחר מזה שמופה (G7-T02-A-Q01ב), והועברו לסעיף זה באותו נושא. נבדק מול הסעיף המודפס: הרמזים מתאימים לו, נכונים ואינם מגלים את התשובה. שני בודקים לא מצאו סיבה לפסול.'),
('G7-T02-B-Q15ה','איזה שינוי מתרחש בפעולת החשבון כאשר מחסרים מספר בעל סימן שלילי?','המירו את חיסור המספר השלילי לחיבור של המספר הנגדי לו, וקבעו את כיוון התנועה על הציר.','בצעו את פעולת החיבור המתקבלת לקביעת הערך המספרי הסופי.','verified','zero-spoiler-v2.1','G7-T02-B-Q01א','חשבו: $(-12) - (-7)$','הרמזים נכתבו לתרגיל אחר מזה שמופה (G7-T02-B-Q01א), והועברו לסעיף זה באותו נושא. נבדק מול הסעיף המודפס: הרמזים מתאימים לו, נכונים ואינם מגלים את התשובה. שני בודקים לא מצאו סיבה לפסול.'),
('G7-T02-E-Q17א','כיצד קיבוץ מספרים לפי סימניהם מסייע בפישוט תרגיל שרשרת?','המירו את כל פעולות החיסור לחיבור של מספרים נגדיים, וקבצו בנפרד את הערכים החיוביים ואת הערכים השליליים.','חשבו את תוצאת החיבור בין הסכום שקיבלתם מכל קבוצה לקבלת התוצאה הסופית.','verified','zero-spoiler-v2.1','G7-T02-C-Q01א','חשבו: $-15 + 8 - (-10) - 12$','הרמזים נכתבו לתרגיל אחר מזה שמופה (G7-T02-E-Q01א), והועברו לסעיף זה באותו נושא. נבדק מול הסעיף המודפס: הרמזים מתאימים לו, נכונים ואינם מגלים את התשובה. שני בודקים לא מצאו סיבה לפסול.'),
('G7-T03-B-Q01ב','כיצד נקבע סימן המכפלה כאשר כופלים מספרים בעלי סימנים זהים?','היזכרו בקשר הסימנים בעת כפל של גורמים בעלי אותו הסימן, וכפלו את ערכי המספרים.','רשמו את המכפלה בצירוף הסימן המתמטי המתאים לפי הכלל.','verified','zero-spoiler-v2.1','G7-T03-A-Q01ב','חשבו: $(-7) × (-4)$','הרמזים נכתבו לתרגיל אחר מזה שמופה (G7-T03-A-Q01ב), והועברו לסעיף זה באותו נושא. נבדק מול הסעיף המודפס: הרמזים מתאימים לו, נכונים ואינם מגלים את התשובה. שני בודקים לא מצאו סיבה לפסול.'),
('G7-T03-B-Q01ג','מהו הכלל לקביעת סימן המכפלה כאשר כופלים מספרים בעלי סימנים מנוגדים?','בדקו מהו הסימן המתקבל מכפל גורמים בעלי סימנים מנוגדים, וכפלו את המרחקים שלהם מאפס.','קבעו את הסימן הסופי לפי הכלל וצרפו אליו את ערך המכפלה שחישבתם.','verified','zero-spoiler-v2.1','G7-T03-A-Q01א','חשבו: $(-5) × (+6)$','הרמזים נכתבו לתרגיל אחר מזה שמופה (G7-T03-A-Q01א), והועברו לסעיף זה באותו נושא. נבדק מול הסעיף המודפס: הרמזים מתאימים לו, נכונים ואינם מגלים את התשובה. שני בודקים לא מצאו סיבה לפסול.'),
('G7-T03-B-Q18א','כיצד כמות הגורמים השליליים במכפלה קובעת האם התוצאה הסופית תהיה חיובית או שלילית?','בצעו את הכפל בהדרגה משמאל לימין, ושימו לב לסימן המתקבל בכל שלב ביניים.','השלימו את פעולת הכפל האחרונה וקבעו את הסימן של התוצאה הסופית.','verified','zero-spoiler-v2.1','G7-T03-B-Q01א','חשבו: $(-2) × (-3) × (-5)$','הרמזים נכתבו לתרגיל אחר מזה שמופה (G7-T03-B-Q01א), והועברו לסעיף זה באותו נושא. נבדק מול הסעיף המודפס: הרמזים מתאימים לו, נכונים ואינם מגלים את התשובה. שני בודקים לא מצאו סיבה לפסול.'),
('G7-T03-E-Q10ג','איזה סוג של כמות (זוגית או שאינה זוגית) של סימנים שליליים מניב מכפלה שלילית?','בדקו מה קורה לסימן המכפלה בכל אחד מהמקרים האפשריים עבור הרכב הסימנים.','נסחו את האפשרויות שבהן המכפלה נותרת בצד השלילי של האפס.','verified','zero-spoiler-v2.1','G7-T03-C-Q01א','מכפלת שלושה מספרים היא מספר שלילי. מה ניתן להסיק לגבי כמות המספרים השליליים מתוכם?','הרמזים נכתבו לתרגיל אחר מזה שמופה (G7-T03-E-Q01א), והועברו לסעיף זה באותו נושא. נבדק מול הסעיף המודפס: הרמזים מתאימים לו, נכונים ואינם מגלים את התשובה. שני בודקים לא מצאו סיבה לפסול.'),
('G7-T04-A-Q06א','מהו הכלל לקביעת סימן המנה כאשר מחלקים מספרים בעלי סימנים זהים?','זהו את הסימן המאפיין חילוק בין ערכים בעלי אותו סימן, ובצעו את פעולת החילוק של המספרים.','כתבו את ערך המנה בצירוף הסימן המתאים שהסקתם.','verified','zero-spoiler-v2.1','G7-T04-A-Q01ב','חשבו: $(-45) / (-9)$','הרמזים נכתבו לתרגיל אחר מזה שמופה (G7-T04-A-Q01ב), והועברו לסעיף זה באותו נושא. נבדק מול הסעיף המודפס: הרמזים מתאימים לו, נכונים ואינם מגלים את התשובה. שני בודקים לא מצאו סיבה לפסול.'),
('G7-T04-A-Q06ג','כיצד כללי הסימנים בחילוק תואמים את כללי הסימנים בפעולת כפל?','קבעו תחילה את סימן התוצאה על פי שילוב הסימנים בתרגיל, ולאחר מכן חלקו את הערכים המספריים.','רשמו את התוצאה שקיבלתם מחילוק המספרים יחד עם הסימן שקבעתם.','verified','zero-spoiler-v2.1','G7-T04-A-Q01א','חשבו: $(-36) / (+4)$','הרמזים נכתבו לתרגיל אחר מזה שמופה (G7-T04-A-Q01א), והועברו לסעיף זה באותו נושא. נבדק מול הסעיף המודפס: הרמזים מתאימים לו, נכונים ואינם מגלים את התשובה. שני בודקים לא מצאו סיבה לפסול.'),
('G7-T04-A-Q11א','איזה חלק בביטוי יש לחשב בעדיפות ראשונה לפי סדר פעולות חשבון?','חשבו תחילה את פעולת החיבור בסוגריים, ולאחר מכן חלקו את התוצאה במספר שמחוץ לסוגריים.','בצעו את חילוק התוצאה שקיבלתם וקבעו את הסימן לפי כללי החילוק.','verified','zero-spoiler-v2.1','G7-T04-B-Q01א','חשבו: $[(-18) + (-6)] / (+4)$','הרמזים נכתבו לתרגיל אחר מזה שמופה (G7-T04-B-Q01א), והועברו לסעיף זה באותו נושא. נבדק מול הסעיף המודפס: הרמזים מתאימים לו, נכונים ואינם מגלים את התשובה. שני בודקים לא מצאו סיבה לפסול.'),
('G7-T04-B-Q02ד','מהו הקשר בין סימני המחולק והמחלק לסימן המנה, ומדוע קיימת הגבלה על הערך שרשאי להופיע במכנה?','היזכרו בקשר בין חילוק לכפל, ובדקו אילו שילובי סימנים של מחולק ומחלק מקיימים את התנאי על המנה.','נסחו את המסקנה לגבי סימן המחלק, ולאחר מכן בחרו דוגמה ובדקו שהמנה מקיימת את כל התנאים.','verified','zero-spoiler-v2.1','G7-T04-C-Q02א','נתון כי המנה של המספרים $a / b$ היא מספר חיובי, וכן ידוע ש-$a$ הוא מספר שלילי. מה ניתן להסיק על הסימן של $b$? נמקו והציגו דוגמה מספרית התואמת את התנאים.','הרמזים נכתבו לתרגיל אחר מזה שמופה (G7-T04-E-Q02א), והועברו לסעיף זה באותו נושא. נבדק מול הסעיף המודפס: הרמזים מתאימים לו, נכונים ואינם מגלים את התשובה. שני בודקים לא מצאו סיבה לפסול.'),
('G7-T05-A-Q01ג','איזו פעולת חשבון קודמת כאשר תרגיל מכיל חיסור לצד כפל?','בצעו תחילה את פעולת הכפל, ולאחר מכן התייחסו לחיסור התוצאה מתוך המספר הפותח.','המירו את חיסור הערך שהתקבל לחיבור מתאים וחשבו את התוצאה הסופית.','verified','zero-spoiler-v2.1','G7-T05-A-Q01א','חשבו: $10 - 3 × (-4)$','הרמזים נכתבו לתרגיל אחר מזה שמופה (G7-T05-A-Q01א), והועברו לסעיף זה באותו נושא. נבדק מול הסעיף המודפס: הרמזים מתאימים לו, נכונים ואינם מגלים את התשובה. שני בודקים לא מצאו סיבה לפסול.'),
